// obs-card click: toggle — re-clicking the selected card deselects
// (back to the Phase 1 face). No jump: the card is already in view.
// follow derives from the click target (Phase 3 manual pin): a
// non-newest obs pins the selection against future landings; the
// newest obs (or a deselect) resumes following.
const selectFromCard = (domId: string) => {
  setNarrOpen(false);
  setSel((prev) =>
    prev.obsId === domId ? { obsId: null, follow: true } : { obsId: domId, follow: domId === lastObsDomId },
  );
};
// ruler-dot click: select only — the doc-delegated [data-dot]
// handler (useRailSync 280–284) already centers + flashes, so no
// rail.jumpToObs here (it would double-jump).
const selectFromDot = (domId: string) => {
  if (sel.obsId !== domId) {
    setNarrOpen(false);
    setSel({ obsId: domId, follow: domId === lastObsDomId });
  }
};
// stack click (Phase 4): select the type's EARLIEST obs. The face
// change collapses the summary body and expands the rail (480ms
// grid-rows); the center+flash jump waits for that expand — the
// domId parks in a ref (no re-render needed) and the railwrap
// transitionend below fires onObsReveal, replacing the design's
// 540ms altGoToObs timer (dc.html 1774–1777) with the actual
// transition boundary. Stacks only render on the summary face
// (rail collapsed), but if the rail is somehow already open the
// jump fires immediately instead. follow mirrors selectFromCard:
// only the session's newest obs keeps following.
const pendingJumpRef = React.useRef<string | null>(null);
const selectFromStack = (domId: string) => {
  setNarrOpen(false);
  setSel({ obsId: domId, follow: domId === lastObsDomId });
  if (face !== 'summary') onObsReveal?.(domId);
  else pendingJumpRef.current = domId;
};

// 20s-quantized wall clock — 0 on the server; every card re-renders
// together on the shared tick (cheap; display times are minute-level)
const nowSec = React.useSyncExternalStore(subscribeClock, readClock, readClockServer) * 20;

const face: 'summary' | 'prompt' | 'obs' = selectedObs
  ? 'obs'
  : session.hasSummary
    ? canToggle
      ? faceChoice
      : 'summary'
    : 'prompt';

// deselect → land on the given face (seg buttons / shrunken prompt
