const deselectTo = (choice: 'summary' | 'prompt') => {
  setSel((prev) => (prev.obsId === null && prev.follow ? prev : { obsId: null, follow: true }));
  setNarrOpen(false);
  if (canToggle) setFaceChoice(choice);

