// stale target once the expand's transitionend fires.
const pendingJumpRef = React.useRef<string | null>(null);

// deselect → land on the given face (seg buttons / shrunken prompt
// row). No-summary sessions derive 'prompt' regardless of choice.
const deselectTo = (choice: 'summary' | 'prompt') => {
  pendingJumpRef.current = null;
  setSel((prev) => (prev.obsId === null && prev.follow ? prev : { obsId: null, follow: true }));
  setNarrOpen(false);
  if (canToggle) setFaceChoice(choice);
};

